window.__CADERNO_PARTS.push("\\\" alt=\\\"Ultrassom cardíaco / FAST — hemopericárdio\\\"><h4>Ultrassom cardíaco / FAST — hemopericárdio</h4><div class=\\\"exam-what\\\"><b>Identifique:</b> Faixa hipoecoica/anecoica ao redor do coração, indicando líquido no pericárdio.</div><div class=\\\"exam-compare\\\"><b>Como diferenciar:</b> FAST identifica líquido; avaliação de tamponamento exige repercussão hemodinâmica e outros achados.</div><div class=\\\"exam-trap\\\"><b>Pegadinha UNIFESP:</b> eFAST sem líquido não exclui lesão de valva, miocárdio ou coronária.</div><figcaption class=\\\"exam-source\\\">ATLS 11ª ed., cap. 6, figura 6-1C, p. 82; recorte do exame ultrassonográfico real publicado no manual.</figcaption></figure><figure class=\\\"realcase-card\\\"><img loading=\\\"lazy\\\" src=\\\"data:image/png;base64,");
